/**
 * UI Strings - Multi-language support
 */

export type Language = 'en' | 'cs' | 'de';

/** The event a main excerpt of the person page shows (personPage.excerptCaption). */
export type PersonPageCaptionEvent = 'birth' | 'birthBaptism' | 'marriage' | 'death' | 'deathBurial';
/** The kind of register a source is (from its title), for the excerpt caption. */
export type PersonPageRegister = 'birth' | 'marriage' | 'death';

export const SUPPORTED_LANGUAGES: { code: Language; name: string }[] = [
    { code: 'en', name: 'English' },
    { code: 'cs', name: 'Čeština' },
    { code: 'de', name: 'Deutsch' }
];

// Type definition for strings structure
type StringsType = typeof stringsEN;

const pluralRulesCache: Partial<Record<Language, Intl.PluralRules>> = {};

/**
 * CLDR plural category of `n` in `lang` (Intl.PluralRules, with a manual
 * fallback for environments without Intl plural data).
 */
export function pluralCategory(lang: Language, n: number): Intl.LDMLPluralRule {
    try {
        let rules = pluralRulesCache[lang];
        if (!rules) {
            rules = new Intl.PluralRules(lang);
            pluralRulesCache[lang] = rules;
        }
        return rules.select(n);
    } catch {
        if (n === 1) return 'one';
        if (lang === 'cs' && Number.isInteger(n) && n >= 2 && n <= 4) return 'few';
        return 'other';
    }
}

/**
 * Pick the grammatical form for a count.
 * English/German: plural(lang, n, one, other).
 * Czech: plural('cs', n, one, few, other) — one = 1, few = 2–4, other = 0 and 5+.
 * Returns the bare word; callers put the number in themselves.
 */
export function plural(lang: Language, n: number, one: string, few: string, other?: string): string {
    const cat = pluralCategory(lang, n);
    if (cat === 'one') return one;
    if (other === undefined) return few;
    return cat === 'few' ? few : other;
}

/**
 * Join list items with the language's "and" before the last one:
 * "2 parents and 1 partner", "2 rodiče a 1 partner". (Intl.ListFormat is not
 * in the ES2020 lib this project targets.)
 */
export function joinAnd(lang: Language, parts: string[]): string {
    const items = parts.filter(Boolean);
    if (items.length <= 1) return items[0] ?? '';
    const and = lang === 'cs' ? 'a' : lang === 'de' ? 'und' : 'and';
    return `${items.slice(0, -1).join(', ')} ${and} ${items[items.length - 1]}`;
}

/** Czech count form shorthand: `${n} ${word}`. */
const nCs = (n: number, one: string, few: string, other: string): string => `${n} ${plural('cs', n, one, few, other)}`;
/** English count form shorthand: `${n} ${word}`. */
const nEn = (n: number, one: string, other: string): string => `${n} ${plural('en', n, one, other)}`;
/** English ordinal: 1st, 2nd, 3rd, 4th, 11th, 21st. */
const ordEn = (n: number): string =>
    `${n}${n % 100 >= 11 && n % 100 <= 13 ? 'th' : (['th', 'st', 'nd', 'rd'][n % 10] ?? 'th')}`;
/**
 * Czech "z" / "ze" before a number as it is read ("z 5", "ze 3", "ze 12"):
 * "ze" before the words that start with s, š, z or a cluster (dvou, tří,
 * čtyř, šesti, sedmi, sta…).
 */
function zeCs(m: number): string {
    const n = Math.abs(Math.trunc(m));
    if (n < 10) return [2, 3, 4, 6, 7].includes(n) ? 'ze' : 'z';
    if (n < 20) return [12, 13, 14, 16, 17].includes(n) ? 'ze' : 'z';
    if (n < 100) return [2, 3, 4, 6, 7].includes(Math.floor(n / 10)) ? 'ze' : 'z';
    if (n < 1000) return [1, 2, 3, 4, 6, 7].includes(Math.floor(n / 100)) ? 'ze' : 'z';
    return 'z';
}
/** Czech "v" / "ve" before an age as it is read ("v 19", "ve 23", "ve 4"). */
function veCs(m: number): string {
    const n = Math.abs(Math.trunc(m));
    if (n < 10) return [2, 3, 4].includes(n) ? 've' : 'v';
    if (n < 20) return [12, 13, 14].includes(n) ? 've' : 'v';
    if (n < 100) return [2, 3, 4].includes(Math.floor(n / 10)) ? 've' : 'v';
    return 'v';
}
/** German count form shorthand: `${n} ${word}`. */
const nDe = (n: number, one: string, other: string): string => `${n} ${plural('de', n, one, other)}`;

/** Czech adverbs for a text's language ("německy"); other languages by Intl. */
const CS_LANG_ADVERB: Record<string, string> = {
    cs: 'česky', de: 'německy', en: 'anglicky', sk: 'slovensky', pl: 'polsky', la: 'latinsky', fr: 'francouzsky',
    it: 'italsky', hu: 'maďarsky', ru: 'rusky', uk: 'ukrajinsky', es: 'španělsky', nl: 'nizozemsky', sl: 'slovinsky',
    hr: 'chorvatsky', sr: 'srbsky', ro: 'rumunsky', yi: 'jidiš', he: 'hebrejsky', sv: 'švédsky', da: 'dánsky', pt: 'portugalsky',
};

/** A language's name for "text in …" (cs: the adverb). Unknown codes stay as they are. */
function langName(ui: 'cs' | 'en' | 'de', code: string): string {
    const base = String(code).toLowerCase().split('-')[0];
    if (ui === 'cs' && CS_LANG_ADVERB[base]) return CS_LANG_ADVERB[base];
    try {
        const name = new Intl.DisplayNames([ui], { type: 'language' }).of(base);
        if (name && name !== base) return ui === 'cs' ? `v jazyce ${name}` : name;
    } catch { /* an invalid code: as it is */ }
    return code;
}
/** A count with the language's digit grouping ("1 284", "1,284", "1.284") — for counts that can run into thousands. */
const numCs = (n: number): string => n.toLocaleString('cs-CZ');
const numEn = (n: number): string => n.toLocaleString('en-US');
const numDe = (n: number): string => n.toLocaleString('de-DE');

/**
 * Tree overview, "Ask the family": a relative named by the path from the
 * chosen person ('F' = father, 'M' = mother, nearest first) — the ancestor at
 * the end of the path, or, with `sibling`, a sibling of that ancestor.
 */
type RelationSibling = { gender?: string; half: boolean };
const relationChain = (path: readonly string[], sibling?: RelationSibling): string[] =>
    sibling ? [...path] : path.slice(0, -1);
/** Czech: "matka otcova otce", "bratr otcova otce", "otec matky otce otcovy matky". */
function relationCs(path: readonly string[], sibling?: RelationSibling): string {
    const nom = (x: string) => x === 'F' ? 'otec' : 'matka';
    const gen = (x: string) => x === 'F' ? 'otce' : 'matky';
    const adj = (x: string, head: string) => x === 'F' ? (head === 'F' ? 'otcova' : 'otcovy') : (head === 'F' ? 'matčina' : 'matčiny');
    const head = sibling
        ? (sibling.gender === 'male' ? `${sibling.half ? 'polorodý ' : ''}bratr`
            : sibling.gender === 'female' ? `${sibling.half ? 'polorodá ' : ''}sestra`
            : `${sibling.half ? 'polorodý ' : ''}sourozenec`)
        : nom(path[path.length - 1] ?? 'F');
    const chain = relationChain(path, sibling);
    if (chain.length === 0) return head;
    if (chain.length === 1) return `${head} ${gen(chain[0])}`;
    const far = chain.slice(2).reverse().map(gen);
    return [head, ...far, `${adj(chain[0], chain[1])} ${gen(chain[1])}`].join(' ');
}
/** English: "father’s father’s mother", "father’s father’s brother". */
function relationEn(path: readonly string[], sibling?: RelationSibling): string {
    const head = sibling
        ? `${sibling.half ? 'half-' : ''}${sibling.gender === 'male' ? 'brother' : sibling.gender === 'female' ? 'sister' : 'sibling'}`
        : (path[path.length - 1] ?? 'F') === 'F' ? 'father' : 'mother';
    return [...relationChain(path, sibling).map(x => x === 'F' ? 'father\u2019s' : 'mother\u2019s'), head].join(' ');
}
/** German: "Mutter des Vaters des Vaters", "Bruder des Vaters". */
function relationDe(path: readonly string[], sibling?: RelationSibling): string {
    const head = sibling
        ? (sibling.half
            ? (sibling.gender === 'male' ? 'Halbbruder' : sibling.gender === 'female' ? 'Halbschwester' : 'Halbgeschwister')
            : (sibling.gender === 'male' ? 'Bruder' : sibling.gender === 'female' ? 'Schwester' : 'Geschwister'))
        : (path[path.length - 1] ?? 'F') === 'F' ? 'Vater' : 'Mutter';
    return [head, ...relationChain(path, sibling).reverse().map(x => x === 'F' ? 'des Vaters' : 'der Mutter')].join(' ');
}

/** Sending to the research: shared count phrases (strings sync / treeSettings). */
const syncChangesEn = (n: number) => nEn(n,'change','changes');
const syncChangesCs = (n: number) => nCs(n,'změna','změny','změn');
const syncChangesDe = (n: number) => nDe(n,'Änderung','Änderungen');
const syncConflictsEn = (c: number) => `${nEn(c,'conflict','conflicts')} to decide`;
const syncConflictsCs = (c: number) => `${nCs(c,'rozpor','rozpory','rozporů')} k rozhodnutí`;
const syncConflictsDe = (c: number) => `${nDe(c,'Widerspruch','Widersprüche')} zu entscheiden`;
const syncWaitingEn = (n: number) => `${nEn(n,'change','changes')} waiting`;
const syncWaitingCs = (n: number) => nCs(n,'úprava čeká','úpravy čekají','úprav čeká');
const syncWaitingDe = (n: number) => `${nDe(n,'Änderung wartet','Änderungen warten')}`;

/** "What will be sent": people and the other changes ("1 person · 6 other changes", only others: "5 changes"). */
const sendCountEn = (n: number, o: number) => o === 0 ? nEn(n,'person','people')
    : n === 0 ? nEn(o,'change','changes') : `${nEn(n,'person','people')} · ${nEn(o,'other change','other changes')}`;
const sendCountCs = (n: number, o: number) => o === 0 ? nCs(n,'osoba','osoby','osob')
    : n === 0 ? nCs(o,'změna','změny','změn') : `${nCs(n,'osoba','osoby','osob')} · ${nCs(o,'další změna','další změny','dalších změn')}`;
const sendCountDe = (n: number, o: number) => o === 0 ? nDe(n,'Person','Personen')
    : n === 0 ? nDe(o,'Änderung','Änderungen') : `${nDe(n,'Person','Personen')} · ${nDe(o,'weitere Änderung','weitere Änderungen')}`;

